declare(strict_types=1);
function manufacturingTaskOperation(array $task,?array $fallback=null):?array{
 $meta=is_array($task['planning_meta']??null)?$task['planning_meta']:decode($task['planning_meta']??null);if(isset($meta['operation_snapshot']))return $meta['operation_snapshot'];$plan=$task['plan_id']??null;if(!$plan)return $fallback;static $cache=[];$key=$task['company_id'].'/'.$plan;
 if(!isset($cache[$key])){$p=one('SELECT snapshot FROM plan_versions WHERE id=? AND company_id=?',[$plan,$task['company_id']]);$cache[$key]=$p?decode($p['snapshot'])['routes']??[]:[];}return array_column($cache[$key][$task['order_id']]??[],null,'id')[$task['operation_id']]??$fallback;
}
function manufacturingAddBusy(array &$busy,string $key,array $slot):void{
 $items=$busy[$key]??[];$items[]=$slot;usort($items,fn($a,$b)=>$a[0]<=>$b[0]);$merged=[];foreach($items as [$a,$b]){if($merged&&$merged[count($merged)-1][1]>=$a)$merged[count($merged)-1][1]=max($merged[count($merged)-1][1],$b);else $merged[]=[$a,$b];}$busy[$key]=$merged;
}
function manufacturingChoosePerson(array $c,array $operations,array $candidates,int $after,array $busy,int $quantity):?string{
 $best=null;foreach($candidates as $pid){$local=$busy;$end=$after;$valid=true;foreach($operations as $op){$fit=plannerFit($c,$op,$end,manufacturingWorkSeconds($op,$quantity,false),$local,[],$pid,$quantity);if(!$fit){$valid=false;break;}plannerReserve($fit,$local);$end=$fit['end'];}if(!$valid)continue;$bucket=companyWageBucket($c,$c['_wage_order']??'draft',$after);$score=[$busy['_wages'][$bucket][$pid]??0,$end,$pid];if($best===null||$score<$best[0])$best=[$score,$pid];}return $best[1]??null;
}
function manufacturingParallelFit(array $c,array $op,int $after,array &$busy,array $stations,int $quantity):?array{
 $best=null;foreach($stations as $station){$fit=plannerFit($c,$op,$after,manufacturingWorkSeconds($op,$quantity,false),$busy,$station,null,$quantity);if($fit&&(!$best||$fit['_score']<$best['_score']))$best=$fit;}return $best;
}
function manufacturingFreeSeconds(array $windows,array $busy):int{
 $total=0;foreach($windows as [$a,$b]){$parts=[[$a,$b]];foreach($busy as [$x,$y]){$next=[];foreach($parts as [$p,$q]){if($y<=$p||$x>=$q)$next[]=[$p,$q];else{if($p<$x)$next[]=[$p,min($q,$x)];if($q>$y)$next[]=[max($p,$y),$q];}}$parts=$next;}foreach($parts as [$p,$q])$total+=$q-$p;}return $total;
}
function manufacturingShiftProjection(array $c,array $o,array $workspace,array $schedule,string $day):array{
 $zone=$c['passport']['timezone'];$date=new DateTimeImmutable($day.' 00:00:00',new DateTimeZone($zone));$windows=dayWindows($date,$c['passport']['shift']);$a=$date->getTimestamp();$b=$date->modify('+1 day')->getTimestamp();$net=array_sum(array_map(fn($s)=>$s[1]-$s[0],$windows));$route=array_column($o['route'],null,'id');$mode=$workspace['mode'];$groups=[];$orderEntries=array_values(array_filter($schedule,fn($t)=>$t['order_id']===$o['id']));
 foreach($orderEntries as $entry){$op=$entry['meta']['operation_snapshot']??$route[$entry['operation_id']]??null;if(!$op)continue;$group=match($mode){'whole'=>'whole','nodes'=>$entry['meta']['work_group']??$op['node_id']??'node-main',default=>$entry['resource_id']};$key=$entry['worker_id'].'/'.$group;$groups[$key]??=['worker_id'=>$entry['worker_id'],'group_id'=>$group,'resource_id'=>$mode==='flow'?$entry['resource_id']:null,'unit'=>$mode==='whole'?'изделие':($mode==='nodes'?'узел / группа':'операция / набор'),'ops'=>[],'batches'=>[]];$groups[$key]['ops'][$op['id']]=$op;$batch=$entry['meta']['batch_id']??$entry['job_key'];$groups[$key]['batches'][$batch][]=$entry;}
 $rows=[];foreach($groups as $g){$duration=0;$known=true;foreach($g['ops'] as $op){$ms=manufacturingMillis($op);if($ms===null)$known=false;else $duration+=$ms;}$blocked=[];foreach($schedule as $t)if($t['worker_id']===$g['worker_id']&&$t['order_id']!==$o['id'])foreach($t['slots']??[[$t['start'],$t['end']]] as [$x,$y])$blocked[]=[plannerTime($x,$zone),plannerTime($y,$zone)];$available=manufacturingFreeSeconds($windows,$blocked);$units=0;$pay=0;$payKnown=true;$first=null;$last=null;
  foreach($g['batches'] as $entries){$finish=max(array_map(fn($t)=>plannerTime($t['end'],$zone),$entries));$begin=min(array_map(fn($t)=>plannerTime($t['start'],$zone),$entries));$allOps=count(array_unique(array_column($entries,'operation_id')))===count($g['ops']);if($allOps&&$finish>$a&&$finish<=$b){$quantity=min(array_column($entries,'quantity'));$units+=$quantity;foreach($entries as $t){$w=$t['meta']['wage_cents']??null;if($w===null)$payKnown=false;else $pay+=$w;}$first=$first===null?$begin:min($first,$begin);$last=$last===null?$finish:max($last,$finish);}}
  $row=['worker_id'=>$g['worker_id'],'group_id'=>$g['group_id'],'resource_id'=>$g['resource_id'],'unit'=>$g['unit'],'norm_millis'=>$known?$duration:null,'net_seconds'=>$net,'available_seconds'=>$available,'theoretical_units'=>$known&&$duration>0?intdiv($available*1000,$duration):null,'planned_units'=>$units,'first_start'=>$first,'last_finish'=>$last,'reason'=>$units===0?'В этой смене нет завершённой единицы: проверьте поступления, предшественников, очередь и занятость':($known&&$duration>0&&$units<intdiv($available*1000,$duration)?'Объём ограничен потребностью, поступлениями или расписанием ресурсов':'Количество следует выполнимому расписанию'),'operation_ids'=>array_keys($g['ops'])];if($c['role']==='owner'||($c['role']==='worker'&&companyWorkerId($c)===$g['worker_id']))$row['wage_cents']=$payKnown?$pay:null;$rows[]=$row;
 }
 $finals=array_values(array_filter($orderEntries,fn($t)=>$t['is_final']&&plannerTime($t['end'],$zone)>$a&&plannerTime($t['end'],$zone)<=$b));$target=$workspace['shift_target']??null;$takt=$target&&$net?intdiv($net*1000,(int)$target):null;$cycles=[];$personCycles=[];if($mode==='flow'){$volume=max(1,array_sum(array_column(array_filter($orderEntries,fn($t)=>$t['is_final']),'quantity')));foreach($orderEntries as $t){$op=$t['meta']['operation_snapshot']??$route[$t['operation_id']]??null;if(!$op)continue;$ms=manufacturingMillis($op,(int)$t['quantity']);if($ms===null)continue;$cycles[$t['resource_id']]=($cycles[$t['resource_id']]??0)+$ms/$volume;$personCycles[$t['worker_id']]=($personCycles[$t['worker_id']]??0)+$ms/$volume;}}$limiting=$cycles?max([...array_values($cycles),...array_values($personCycles)]):null;
 return ['day'=>$day,'timezone'=>$zone,'net_seconds'=>$net,'mode'=>$mode,'rows'=>$rows,'finished_garments'=>array_sum(array_column($finals,'quantity')),'required_units'=>$target,'takt_millis'=>$takt,'limiting_cycle_millis'=>$limiting,'limiting_resource'=>$limiting===null?null:array_search($limiting,$cycles,true),'cycles'=>$cycles,'worker_cycles'=>$personCycles,'cycle_model'=>'Средняя нагрузка реального ресурса на изделие выбранного распределения; пуск и очереди определяет расписание','bottleneck'=>$takt!==null&&$limiting!==null&&$limiting>$takt,'note'=>'Норма времени, верхняя оценка и завершённое сменное задание различаются. Готовые изделия считаются только по конечной операции; узлы и операции не складываются с ними.'];
}
function preparationReserveSchedule(array $c,array $snapshot):void{
 if(!manufacturingAvailable())return;$byOrder=[];foreach($snapshot['schedule'] as $e)if(empty($e['pinned'])&&!$e['dependencies'])$byOrder[$e['order_id']][]=$e;
 foreach($byOrder as $oid=>$entries){$o=one('SELECT * FROM orders WHERE id=? AND company_id=?',[$oid,$c['id']]);if(!$o)continue;$o['route']=decode($o['route']);$s=preparationState($c,$o);$lots=array_column($s['tranches'],null,'id');$seen=[];
  foreach($entries as $e){$batch=$e['meta']['batch_id']??null;$lot=$e['meta']['tranche_id']??null;if(!$batch||!$lot||isset($seen[$batch]))continue;$seen[$batch]=true;$t=$lots[$lot]??null;if(!$t)fail('Источник комплектации изменился',409);$existing=rows('SELECT kind,quantity FROM preparation_movements WHERE company_id=? AND order_id=? AND batch_key=?',[$c['id'],$oid,$batch]);$reserved=0;$planned=0;foreach($existing as $m){$q=(int)$m['quantity'];if($m['kind']==='reserve')$reserved+=$q;elseif(in_array($m['kind'],['issue','unreserve'],true))$reserved-=$q;elseif($m['kind']==='plan_reserve')$planned+=$q;elseif($m['kind']==='unplan')$planned-=$q;}$issued=preparationBatchIssued($c,$o,$batch);$want=max(0,(int)$e['quantity']-$issued-max(0,$reserved)-max(0,$planned));if(!$want)continue;$free=max(0,(int)$t['free']);$take=min($want,$free);if($take){preparationMovement($c,$o,$lot,$batch,'reserve',$take,['plan'=>'published']);$lots[$lot]['free']-=$take;}$wait=$want-$take;if($wait)preparationMovement($c,$o,$lot,$batch,'plan_reserve',$wait,['plan'=>'published']);}
 }
}
function preparationReleaseTaskReservations(array $c,array $task):void{
 if(!manufacturingAvailable())return;$m=decode($task['planning_meta']??null);$batch=$m['batch_id']??null;if(!$batch)return;$o=['id'=>$task['order_id']];$totals=[];foreach(rows('SELECT tranche_id,kind,quantity FROM preparation_movements WHERE company_id=? AND order_id=? AND batch_key=?',[$c['id'],$o['id'],$batch]) as $r){$id=$r['tranche_id'];$totals[$id]??=['r'=>0,'p'=>0];$q=(int)$r['quantity'];if($r['kind']==='reserve')$totals[$id]['r']+=$q;elseif(in_array($r['kind'],['issue','unreserve'],true))$totals[$id]['r']-=$q;elseif($r['kind']==='plan_reserve')$totals[$id]['p']+=$q;elseif($r['kind']==='unplan')$totals[$id]['p']-=$q;}foreach($totals as $id=>$v){if($v['r']>0)preparationMovement($c,$o,$id,$batch,'unreserve',$v['r'],['task_id'=>$task['id']]);if($v['p']>0)preparationMovement($c,$o,$id,$batch,'unplan',$v['p'],['task_id'=>$task['id']]);}
}
function manufacturingAssertResourcesFree(array $c,array $people,array $resources,?string $taskId=null,?string $cutId=null,?string $layId=null):void{
 $personMap=array_column($c['passport']['people'],null,'id');$resourceMap=array_column($c['passport']['resources'],null,'id');foreach($people as $id)if(empty($personMap[$id]['active']))fail('Исполнитель сейчас недоступен');foreach($resources as $id)if(empty($resourceMap[$id]['active']))fail('Оборудование сейчас недоступно');
 $keys=array_merge(array_map(fn($v)=>'p:'.$v,$people),array_map(fn($v)=>'r:'.$v,$resources));foreach($resources as $rid){$station=companyWorkplaceFor($c['passport'],$rid);if($station)$keys[]='s:'.$station;}
 foreach(rows("SELECT id,title,worker_id,resource_id FROM tasks WHERE company_id=? AND state='running'",[$c['id']]) as $t){if($t['id']===$taskId)continue;$other=['p:'.$t['worker_id'],'r:'.$t['resource_id']];$station=companyWorkplaceFor($c['passport'],$t['resource_id']);if($station)$other[]='s:'.$station;if(array_intersect($keys,$other))fail('RESOURCE_CONFLICT: ресурс занят — '.$t['title']);}
 if(manufacturingAvailable())foreach(rows("SELECT id,state_json,calculation_json FROM cutting_plans WHERE company_id=? AND status='in_progress'",[$c['id']]) as $p){$s=decode($p['state_json']);foreach(decode($p['calculation_json'])['lays']??[] as $l){if($p['id']===$cutId&&$l['id']===$layId)continue;if(($s['execution'][$l['id']]['state']??'')!=='running')continue;if(array_intersect($keys,$l['resource_keys']??[]))fail('RESOURCE_CONFLICT: ресурс занят активным настилом');}}
}
function preparationReserveTaskInput(array $c,array $task):void{
 if(!manufacturingAvailable()||decode($task['dependencies']))return;$o=one('SELECT * FROM orders WHERE id=? AND company_id=?',[$task['order_id'],$c['id']]);if(!$o)return;$o['route']=decode($o['route']);$m=decode($task['planning_meta']??null);$batch=$m['batch_id']??'legacy-'.$o['id'];$variant=$m['variant_id']??'variant-main';$s=preparationState($c,$o);$issued=preparationBatchIssued($c,$o,$batch);$reserved=0;foreach(rows('SELECT kind,quantity FROM preparation_movements WHERE company_id=? AND order_id=? AND batch_key=?',[$c['id'],$o['id'],$batch]) as $move)$reserved+=match($move['kind']){'reserve'=>(int)$move['quantity'],'issue','unreserve'=>-(int)$move['quantity'],default=>0};$need=max(0,(int)$task['quantity']-$issued-max(0,$reserved));
 foreach($s['tranches'] as $lot){if($variant!=='variant-main'&&$variant!==$lot['variant_id'])continue;if(!empty($m['tranche_id'])&&$m['tranche_id']!==$lot['id'])continue;$take=min($need,(int)$lot['free']);if(!$take)continue;preparationMovement($c,$o,$lot['id'],$batch,'reserve',$take,['task_id'=>$task['id'],'at_start'=>true]);$planned=0;foreach(rows('SELECT kind,quantity FROM preparation_movements WHERE company_id=? AND order_id=? AND tranche_id=? AND batch_key=?',[$c['id'],$o['id'],$lot['id'],$batch]) as $move)$planned+=match($move['kind']){'plan_reserve'=>(int)$move['quantity'],'unplan'=>-(int)$move['quantity'],default=>0};if($planned>0)preparationMovement($c,$o,$lot['id'],$batch,'unplan',min($planned,$take),['promoted_to_accepted_reserve'=>true]);$need-=$take;if(!$need)break;}
}
